import { ExtensionSlot } from '@gainwell/extensions-sdk-react';

export const ClaimsDetailPage = ({ claimId }) => {
  return (
    <div>
      <h1>Claim Details</h1>

      {/* Extension point for custom validation widgets */}
      <ExtensionSlot
        name="claims.detail.validation"
        props={{ claimId, tenantId: currentTenant }}
        strategy="append"
        fallback={<div>No validation extensions</div>}
